    94→public(package) fun new_pool_reward_manager(
    95→    ctx: &mut TxContext,
    96→): PoolRewardManager{
    97→    PoolRewardManager{
    98→        id: object::new(ctx),
    99→        total_shares: 0,
   100→        pool_rewards: vector::empty(),
