   106→public(package) fun close_pool_reward<CoinType>(
   107→    pool_reward_manager: &mut PoolRewardManager,
   108→    index: u64,
   109→    clock: &Clock
   110→): Balance<CoinType>{
   111→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index);
   112→    let PoolReward{
   113→        id,
   114→        pool_reward_manager_id: _,
   115→        coin_type: _,
   116→        start_time_ms: _,
   117→        end_time_ms,
   118→        total_rewards: _,
   119→        allocated_rewards: _,
   120→        cumulative_rewards_per_share: _,
   121→        num_obligation_reward_managers,
   122→        mut additional_fields,
   123→    } = optional_pool_reward.extract();
   124→
   125→    object::delete(id);
   126→
   127→    let cur_time_ms = clock.timestamp_ms();
   128→
   129→    assert!(cur_time_ms >= end_time_ms, error::liquidity_mining_pool_reward_period_not_over());
   130→    assert!(num_obligation_reward_managers == 0, error::liquidity_mining_not_all_rewards_claimed());
   131→
   132→    let reward_balance = additional_fields.remove<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   133→    additional_fields.destroy_empty();
   134→    
   135→    reward_balance
   136→}   
   137→
   138→public(package) fun cancel_pool_reward<CoinType>(
   139→    pool_reward_manager: &mut PoolRewardManager,
   140→    index: u64,
   141→    clock: &Clock,
   142→): Balance<CoinType>{
   143→    update_pool_reward_manager(pool_reward_manager, clock);
   144→    
   145→    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index).borrow_mut();
   146→    let cur_time_ms = clock.timestamp_ms();
   147→    
   148→    let unallocated_rewards = 
   149→        float::from(pool_reward.total_rewards).sub(
   150→        pool_reward.allocated_rewards
   151→        ).floor();
   152→    
   153→    pool_reward.end_time_ms = cur_time_ms;
   154→    pool_reward.total_rewards = 0;
   155→
   156→    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   157→
   158→    reward_balance.split(unallocated_rewards)
   159→}
   160→
   161→public(package) fun add_pool_reward<CoinType>(
   162→    pool_reward_manager: &mut PoolRewardManager,
   163→    rewards: Balance<CoinType>,
   164→    start_time_ms: u64,
   165→    end_time_ms: u64,
   166→    clock: &Clock,
   167→    ctx: &mut TxContext
   168→){
   169→    assert!(start_time_ms >= clock.timestamp_ms(), error::liquidity_mining_invalid_start_time());
   170→    assert!(end_time_ms - start_time_ms >= MIN_REWARD_PERIOD_MS, error::liquidity_mining_invalid_time());
   171→
   172→    let pool_reward = PoolReward {
   173→        id: object::new(ctx),
   174→        pool_reward_manager_id: object::id(pool_reward_manager),
   175→        coin_type: type_name::with_defining_ids<CoinType>(),
   176→        start_time_ms,
   177→        end_time_ms,
   178→        total_rewards: rewards.value(),
   179→        allocated_rewards: float::from(0),
   180→        cumulative_rewards_per_share: float::from(0),
   181→        num_obligation_reward_managers: 0,
   182→        additional_fields: {
   183→            let mut bag = bag::new(ctx);
   184→            bag.add(RewardBalance<CoinType>{}, rewards);
   185→            bag
   186→        },
   187→    };
   188→
   189→    let i = find_available_index(pool_reward_manager);
   190→    assert!(i < MAX_REWARDS, error::liquidity_mining_max_concurrent_pool_rewards_violated());
   191→    
   192→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(i);
   193→    optional_pool_reward.fill(pool_reward);
   194→}
   195→
   196→public(package) fun new_obligation_reward_manager(
   197→    pool_reward_manager: &mut PoolRewardManager,
   198→    obligation_id: ID,
   199→    clock: &Clock,
   200→){
   201→    let obligation_reward_manager = ObligationRewardManager{
   202→        share: 0,
   203→        rewards: vector::empty(),
   204→        last_update_time_ms: clock.timestamp_ms(),
   205→    };
   206→
   207→    pool_reward_manager.obligation_reward_managers.add(obligation_id, obligation_reward_manager);
   208→    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, true);
   209→}
   210→
   211→public(package) fun change_obligation_reward_manager_share(
   212→    pool_reward_manager: &mut PoolRewardManager,
   213→    obligation_id: ID,
   214→    new_share: u64,
   215→    clock: &Clock,
   216→){
   217→    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);
   218→
   219→    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);
   220→    
   221→    pool_reward_manager.total_shares = 
   222→        pool_reward_manager.total_shares - obligation_reward_manager.share + new_share;
   223→    
   224→    obligation_reward_manager.share = new_share;
   225→}
   226→
   227→public(package) fun claim_rewards<CoinType>(
   228→    pool_reward_manager: &mut PoolRewardManager,
   229→    obligation_id: ID,
   230→    clock: &Clock,
   231→    reward_index: u64,
   232→): Balance<CoinType>{
   233→    update_obligation_reward_manager(pool_reward_manager, obligation_id, clock, false);
   234→
   235→    let pool_reward = pool_reward_manager.pool_rewards.borrow_mut(reward_index).borrow_mut();
   236→    
   237→    assert!(pool_reward.coin_type == type_name::with_defining_ids<CoinType>(), error::liquidity_mining_invalid_type());
   238→
   239→    let obligation_reward_manager = pool_reward_manager.obligation_reward_managers.borrow_mut(obligation_id);
   240→
   241→    let reward_tracker = obligation_reward_manager.rewards.borrow_mut(reward_index);
   242→    assert!(reward_tracker.is_some(), error::liquidity_mining_no_reward_to_claim());
   243→
   244→    let reward = reward_tracker.borrow_mut();
   245→    let claimable_rewards = reward.earned_rewards.floor();
   246→    reward.earned_rewards = reward.earned_rewards.sub(float::from(claimable_rewards));
   247→
   248→    let reward_balance = pool_reward.additional_fields.borrow_mut<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   249→
   250→    if (clock.timestamp_ms() >= pool_reward.end_time_ms) {
   251→        // the pool reward has ended, purge the reward at reward_index
   252→        let ObligationReward{
   253→            pool_reward_id: _,
   254→            earned_rewards: _,
   255→            cumulative_rewards_per_share: _,
   256→        } = reward_tracker.extract();
   257→
   258→        pool_reward.num_obligation_reward_managers = pool_reward.num_obligation_reward_managers - 1;
   259→    };
   260→
   261→    reward_balance.split(claimable_rewards)
   262→}
