   478→#[test]
   479→fun test_pool_reward_manager_basic() {
   480→    use sui::test_scenario::{Self};
   481→
   482→    let owner = @0x26;
   483→    let mut scenario = test_scenario::begin(owner);
   484→
   485→    let ctx = test_scenario::ctx(&mut scenario);
   486→    let mut clock = clock::create_for_testing(ctx);
   487→    clock.set_for_testing(0);
   488→    
   489→    let mut pool_reward_manager = new_pool_reward_manager(ctx);
   490→    let usdc = sui::balance::create_for_testing<USDC>(100 * 1_000_000);
   491→    
   492→    add_pool_reward(&mut pool_reward_manager, usdc, 0, 20 * MILLISECONDS_IN_DAY, &clock, ctx);
   493→
   494→    let obligation_id_1 = object::id_from_address(@0x1);
   495→    new_obligation_reward_manager(&mut pool_reward_manager, obligation_id_1, &clock);
   496→
   497→    change_obligation_reward_manager_share(
   498→        &mut pool_reward_manager,
   499→        obligation_id_1,
   500→        100,
   501→        &clock,
   502→    );
   503→
   504→    // at this point, obligation 1 has earned 50 dollars
   505→    clock.set_for_testing(5 * MILLISECONDS_IN_DAY);
   506→    {
   507→        let usdc = claim_rewards<USDC>(
   508→            &mut pool_reward_manager,
   509→            obligation_id_1,
   510→            &clock,
   511→            0,
   512→        );
   513→        assert!(usdc.value() == 25 * 1_000_000, 0);
   514→        std::unit_test::destroy(usdc);
